import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

// ─── STAKEHOLDER HIGH-TIER TRANSLATION MATRIX ───
const zoneLocationMapping = {
  "Node1_Zone_Demand": {
    sectionTitle: "SECTION 1",
    label: "Primary Intake Node 1",
    color: "#ef4444",      // High visibility Red
    bgGradient: "linear-gradient(135deg, #fef2f2 0%, #fee2e2 100%)"
  },
  "Node2_Zone_Demand": {
    sectionTitle: "SECTION 2",
    label: "Distribution Main Node 2",
    color: "#3b82f6",      // Professional Navy/Blue
    bgGradient: "linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%)"
  },
  "Node5_Zone_Demand": {
    sectionTitle: "SECTION 3",
    label: "Storage Feeder Node 5",
    color: "#10b981",      // Eco Green
    bgGradient: "linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)"
  },
  "Node7_Zone_Demand": {
    sectionTitle: "SECTION 4",
    label: "Booster Regulator Node 7",
    color: "#f59e0b",      // Warning Orange
    bgGradient: "linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%)"
  }
};

const DemandForecasting = () => {
  const navigate = useNavigate();
  const [forecastData, setForecastData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchLiveDemandData = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/weather/water-demand`);      
      if (!response.ok) throw new Error(`Server status signature: ${response.status}`);
      const result = await response.json();
      if (result.success) {
        setForecastData(result);
        setError(null);
      } else {
        throw new Error(result.error || 'Failed parsing operational matrices pipeline.');
      }
    } catch (err) {
      console.error('Telemetry drop error:', err);
      setError(err.message || 'Failed connecting to real-time S3 telemetry infrastructure.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLiveDemandData();
    const telemetryInterval = setInterval(fetchLiveDemandData, 30000);
    return () => clearInterval(telemetryInterval);
  }, []);

  // Compute aggregated real-time metrics for the top executive summary strip
  const totalFlowRate = forecastData?.demand 
    ? Object.values(forecastData.demand).reduce((acc, curr) => acc + Number(curr), 0).toFixed(2)
    : "0.00";

  const monitoredSectionsCount = forecastData?.demand 
    ? Object.keys(forecastData.demand).length 
    : 0;

  return (
    <div style={{ padding: '32px 24px', fontFamily: '"Inter", "Segoe UI", system-ui, sans-serif', maxWidth: '1440px', margin: '0 auto', backgroundColor: '#f1f5f9', minHeight: '100vh', color: '#1e293b' }}>
      
      {/* Premium Glassmorphism Navigation Bar */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px', flexWrap: 'wrap', gap: '16px' }}>
        <button 
          onClick={() => navigate('/weather-home')}
          style={{ cursor: 'pointer', padding: '12px 20px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '10px', color: '#475569', boxShadow: '0 1px 3px rgba(0,0,0,0.05)', transition: 'all 0.2s' }}
          onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#f8fafc'; e.currentTarget.style.transform = 'translateX(-2px)'; }}
          onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = '#ffffff'; e.currentTarget.style.transform = 'none'; }}
        >
          <i className="fas fa-arrow-left" style={{ fontSize: '14px' }}></i> Back to System Control
        </button>

        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontSize: '12px', background: '#e2e8f0', color: '#334155', padding: '6px 14px', borderRadius: '6px', fontWeight: '700', letterSpacing: '0.5px' }}>
            PROJECT TESTBED ID: MEITY-WDM-2026
          </span>
          <span style={{ fontSize: '12px', background: '#d1fae5', color: '#065f46', padding: '6px 14px', borderRadius: '6px', fontWeight: '700', display: 'flex', alignItems: 'center', gap: '8px', boxShadow: '0 1px 2px rgba(16,185,129,0.1)' }}>
            <span style={{ width: '8px', height: '8px', backgroundColor: '#10b981', borderRadius: '50%', display: 'inline-block', animation: 'pulse-glow 2s infinite' }}></span>
            S3 MATRIX ONLINE
          </span>
        </div>
      </div>

      {/* Main Title Architecture */}
      <header style={{ marginBottom: '36px' }}>
        <h1 style={{ color: '#0f172a', margin: '0 0 8px 0', fontSize: '32px', fontWeight: '800', letterSpacing: '-0.5px' }}>
          Hydraulic Network Demand Telemetry
        </h1>
        <p style={{ color: '#64748b', margin: '0', fontSize: '16px', fontWeight: '400' }}>
          Real-time algorithmic zone demand allocations flowing via edge sensor array architectures.
        </p>
      </header>

      {/* Executive Key Metrics Bar */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '20px', marginBottom: '32px' }}>
        <div style={{ backgroundColor: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 1px 3px rgba(0,0,0,0.02)' }}>
          <span style={{ fontSize: '13px', color: '#64748b', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Total Network Demand</span>
          <div style={{ fontSize: '28px', fontWeight: '800', color: '#0f172a', marginTop: '6px' }}>
            {totalFlowRate} <span style={{ fontSize: '16px', fontWeight: '500', color: '#64748b' }}>m³/h</span>
          </div>
        </div>
        <div style={{ backgroundColor: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 1px 3px rgba(0,0,0,0.02)' }}>
          <span style={{ fontSize: '13px', color: '#64748b', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Monitored Segments</span>
          <div style={{ fontSize: '28px', fontWeight: '800', color: '#0284c7', marginTop: '6px' }}>
            {monitoredSectionsCount} <span style={{ fontSize: '16px', fontWeight: '500', color: '#64748b' }}>Active Sections</span>
          </div>
        </div>
        <div style={{ backgroundColor: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 1px 3px rgba(0,0,0,0.02)' }}>
          <span style={{ fontSize: '13px', color: '#64748b', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Telemetry Refresh Cycle</span>
          <div style={{ fontSize: '15px', fontWeight: '600', color: '#334155', marginTop: '16px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <i className="fas fa-history" style={{ color: '#64748b' }}></i> {forecastData?.timestamp || 'Awaiting Cycle...'}
          </div>
        </div>
      </div>

      {/* Screen Loader / Error Interceptors */}
      {loading ? (
        <div style={{ padding: '80px 0', textAlign: 'center', background: '#ffffff', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
          <div style={{ width: '40px', height: '40px', border: '3px solid #f1f5f9', borderTop: '3px solid #3b82f6', borderRadius: '50%', animation: 'spin 0.8s linear infinite', margin: '0 auto 20px auto' }}></div>
          <p style={{ fontSize: '16px', color: '#475569', fontWeight: '500' }}>Initializing secure AWS S3 matrix stream connection...</p>
        </div>
      ) : error ? (
        <div style={{ padding: '32px', background: '#fef2f2', border: '1px solid #fee2e2', borderRadius: '12px', color: '#991b1b' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '12px' }}>
            <i className="fas fa-exclamation-triangle" style={{ fontSize: '24px' }}></i>
            <h4 style={{ margin: '0', fontSize: '18px', fontWeight: '700' }}>Telemetry Sync Blockedage</h4>
          </div>
          <p style={{ margin: '0 0 20px 0', fontSize: '15px', color: '#b91c1c' }}>{error}</p>
          <button onClick={fetchLiveDemandData} style={{ padding: '10px 20px', backgroundColor: '#991b1b', color: '#ffffff', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '600', fontSize: '14px' }}>
            Re-verify S3 Stream Handshake
          </button>
        </div>
      ) : (
        <>
          {/* Main Dashboard Panel Layer */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '28px', marginBottom: '36px' }}>
            {forecastData?.demand && Object.keys(forecastData.demand).length > 0 ? (
              Object.entries(forecastData.demand).map(([nodeKey, val]) => {
                const systemSegment = zoneLocationMapping[nodeKey] || {
                  sectionTitle: "SYSTEM NODE",
                  label: `Identifier Reference: ${nodeKey}`,
                  color: "#64748b",
                  bgGradient: "linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)"
                };

                // Mathematical percentage mapping helper to populate the visual progress track
                const numericalVal = Number(val);
                const safetyThresholdPercent = Math.min(100, Math.max(5, (numericalVal / 15) * 100));

                return (
                  <div 
                    key={nodeKey}
                    style={{ backgroundColor: '#ffffff', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.02), 0 2px 4px -1px rgba(0,0,0,0.01)', overflow: 'hidden', transition: 'transform 0.2s, box-shadow 0.2s' }}
                    onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-4px)'; e.currentTarget.style.boxShadow = '0 12px 20px -8px rgba(0,0,0,0.08)'; }}
                    onMouseLeave={(e) => { e.currentTarget.style.transform = 'none'; e.currentTarget.style.boxShadow = '0 4px 6px -1px rgba(0,0,0,0.02), 0 2px 4px -1px rgba(0,0,0,0.01)'; }}
                  >
                    {/* Header Banner Inside Card */}
                    <div style={{ background: systemSegment.bgGradient, padding: '20px 24px', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <h3 style={{ margin: '0 0 2px 0', fontSize: '18px', fontWeight: '800', color: '#0f172a', letterSpacing: '-0.3px' }}>
                          {systemSegment.sectionTitle}
                        </h3>
                        <span style={{ fontSize: '12px', color: '#64748b', fontWeight: '600' }}>
                          {systemSegment.label}
                        </span>
                      </div>
                      <span style={{ fontSize: '11px', fontFamily: 'monospace', fontWeight: '700', backgroundColor: '#ffffff', color: '#334155', padding: '4px 8px', borderRadius: '4px', border: '1px solid #e2e8f0' }}>
                        {nodeKey.split('_')[0]}
                      </span>
                    </div>

                    {/* Data Display Layout */}
                    <div style={{ padding: '24px' }}>
                      <div style={{ display: 'flex', alignItems: 'baseline', gap: '6px', marginBottom: '20px' }}>
                        <span style={{ fontSize: '44px', fontWeight: '800', color: '#0f172a', letterSpacing: '-1px' }}>
                          {val}
                        </span>
                        <span style={{ fontSize: '16px', color: '#475569', fontWeight: '700' }}>m³/h</span>
                      </div>

                      {/* ADVANCED STEP: Live Linear Status Gauge Track */}
                      <div style={{ marginBottom: '16px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: '#64748b', fontWeight: '600', marginBottom: '6px' }}>
                          <span>VOLUMETRIC CAPACITY RATIO</span>
                          <span>{Math.round(safetyThresholdPercent)}%</span>
                        </div>
                        <div style={{ width: '100%', height: '8px', backgroundColor: '#f1f5f9', borderRadius: '4px', overflow: 'hidden' }}>
                          <div style={{ height: '100%', width: `${safetyThresholdPercent}%`, backgroundColor: systemSegment.color, borderRadius: '4px', transition: 'width 1s ease-in-out' }}></div>
                        </div>
                      </div>

                      {/* Status Bottom Badge Footer */}
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', paddingTop: '14px', borderTop: '1px solid #f1f5f9' }}>
                        <span style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#10b981' }}></span>
                        <span style={{ fontSize: '12px', color: '#047857', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.3px' }}>
                          Flow Threshold Integrity Secure
                        </span>
                      </div>
                    </div>
                  </div>
                );
              })
            ) : (
              <div style={{ gridColumn: '1/-1', padding: '40px', textAlign: 'center', color: '#64748b', background: '#ffffff', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
                No database metrics captured inside this polling partition.
              </div>
            )}
          </div>

          {/* Institutional Compliance Footnote Element */}
          <div style={{ backgroundColor: '#ffffff', borderRadius: '16px', border: '1px solid #e2e8f0', padding: '24px', display: 'flex', gap: '20px', alignItems: 'flex-start', boxShadow: '0 1px 3px rgba(0,0,0,0.01)' }}>
            <div style={{ backgroundColor: '#eff6ff', padding: '12px', borderRadius: '10px', color: '#2563eb' }}>
              <i className="fas fa-shield-alt" style={{ fontSize: '20px' }}></i>
            </div>
            <div>
              <h4 style={{ margin: '0 0 6px 0', color: '#0f172a', fontSize: '16px', fontWeight: '700' }}>
                System Calibration Notice
              </h4>
              <p style={{ margin: '0', color: '#475569', fontSize: '14px', lineHeight: '1.6' }}>
                This tracking terminal displays algorithmic demand metrics from the *Artificial Intelligence Integrated Water Distribution and Monitoring System* patent layer. Stream records are gathered continually to ensure high performance and transparency across regional networks.
              </p>
            </div>
          </div>
        </>
      )}

      {/* Global Embedded Keyframes Definitions */}
      <style>{`
        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
        @keyframes pulse-glow { 0% { transform: scale(0.95); opacity: 0.5; } 50% { transform: scale(1.1); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.5; } }
      `}</style>
    </div>
  );
};

export default DemandForecasting;
